import {ROLES} from './content.js?v=missions12';
export {ROLES};
export const RANKS=[{name:'Junior',xp:0},{name:'Middle',xp:180},{name:'Senior',xp:420},{name:'Senior+',xp:720},{name:'Тимлид',xp:1050}];
export const MODES={easy:{name:'Знакомство',cost:25,stress:6,boss:150},normal:{name:'Карьера',cost:40,stress:10,boss:120},hard:{name:'Вызов',cost:60,stress:14,boss:90}};
export const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
export function role(s){return ROLES.find(r=>r.id===s.role);}
export function rank(s){return RANKS.reduce((n,r,i)=>s.xp>=r.xp?i:n,0);}
export function createGame(roleId='frontend',name='Игрок',mode='normal'){if(!ROLES.some(r=>r.id===roleId)||!MODES[mode])throw Error('Выбери профессию и режим');return {version:2,role:roleId,name:String(name).trim().slice(0,22)||'Игрок',mode,stage:'quiz',quizIndex:0,quizAnswers:[],quizFeedback:null,bossIndex:0,bossHp:3,bossRemaining:MODES[mode].boss,bossWrong:[],bossFeedback:null,day:1,xp:0,money:600,focus:80,stress:15,reputation:50,score:0,inventory:[],actions:0,taskDone:false,taskAttempt:0,lastTask:null,company:null,log:[],pending:null,nextCrisis:false,worldSeconds:0,nextEvent:45,lastXpDay:1,workCount:0,releaseCount:0,mastered:[],finished:false};}
// Guard in the engine, not only a disabled button: all entry points obey the same progression.
function requireStage(s,stage='career'){if(s.stage!==stage)throw Error('Сначала заверши обучение и босса');if(s.pending)throw Error('Сначала выбери решение события');}
export function quizQuestion(s){return role(s).questions[s.quizIndex];}
export function answerQuiz(s,index){if(s.stage!=='quiz'||s.quizFeedback)throw Error('Сначала прочитай разбор');const q=quizQuestion(s);if(!Number.isInteger(index)||!q.options[index])throw Error('Выбери ответ');const correct=index===q.answer;s.quizAnswers.push({id:q.id,correct});s.quizFeedback={correct,why:q.why};return s.quizFeedback;}
export function nextQuiz(s){if(s.stage!=='quiz'||!s.quizFeedback)throw Error('Сначала ответь');s.quizIndex++;s.quizFeedback=null;if(s.quizIndex===4)s.stage='bossReady';}
export function startBoss(s){if(!['bossReady','bossFailed'].includes(s.stage))throw Error('Босс пока недоступен');Object.assign(s,{stage:'boss',bossIndex:0,bossHp:3,bossRemaining:MODES[s.mode].boss,bossWrong:[],bossFeedback:null});}
export function bossQuestion(s){return role(s).questions[4+s.bossIndex];}
export function tickBoss(s,dt){if(s.stage!=='boss')return;if(!Number.isFinite(dt)||dt<0)throw Error('Некорректное время');s.bossRemaining=Math.max(0,s.bossRemaining-dt);if(s.bossRemaining===0)s.stage='bossFailed';}
export function answerBoss(s,index){if(s.stage!=='boss'||s.bossFeedback?.correct)throw Error('Сначала продолжи');const q=bossQuestion(s);if(!Number.isInteger(index)||!q.options[index]||s.bossWrong.includes(index))throw Error('Выбери другой вариант');const correct=index===q.answer;s.bossFeedback={correct,why:q.why};if(!correct){s.bossHp--;s.bossWrong.push(index);if(s.bossHp===0)s.stage='bossFailed';}return s.bossFeedback;}
export function nextBoss(s){if(s.stage!=='boss'||!s.bossFeedback?.correct)throw Error('Нужно решить этап');s.bossIndex++;s.bossWrong=[];s.bossFeedback=null;if(s.bossIndex===3){s.stage='career';s.xp=40;s.score=100;s.money+=100;s.log.unshift('Босс пройден. Открыта карьера. +40 XP, +100 CR.');}}
export function shop(s){return [{id:'chair',name:'Эргономичное кресло',price:180,rank:0,description:'Отдых восстанавливает на 10 фокуса больше. Кресло появляется в студии.'},{id:'plant',name:'Растение на стол',price:120,rank:0,description:'В конце каждого дня снимает ещё 3 стресса. Украшает студию.'},{id:'monitor',name:'Второй экран',price:300,rank:1,description:'Рабочая задача даёт +15 XP. Дополнительный монитор виден на столе.'},{id:'special',name:role(s).item,price:550,rank:2,description:'Профессиональный комплект: +80 CR за верно решённую рабочую задачу.'},{id:'automation',name:'Автоматизация рутины',price:850,rank:3,description:'Рабочая задача отнимает на 8 фокуса меньше.'}];}
export function buy(s,id){requireStage(s);const item=shop(s).find(i=>i.id===id);if(!item)throw Error('Предмет не найден');if(s.inventory.includes(id))throw Error('Уже куплено');if(rank(s)<item.rank)throw Error('Нужен ранг '+RANKS[item.rank].name);if(s.money<item.price)throw Error('Не хватает денег');s.money-=item.price;s.inventory.push(id);s.log.unshift(`Покупка: ${item.name}, −${item.price} CR.`);}
export function actions(s){return [{id:'rest',name:'Сделать перерыв',description:`+${s.inventory.includes('chair')?40:30} фокуса, −22 стресса. Бесплатно.`},{id:'learn',name:role(s).action,description:'+20 XP, −10 фокуса. Стоит 30 CR.'},{id:'talk',name:rank(s)>=3?'Провести ревью коллеги':'Попросить помощи',description:'+8 репутации, −12 стресса. Бесплатно.'},{id:'freelance',name:({security:'Проверить настройки доступа',qa:'Проверить форму клиента',backend:'Настроить API для клиента',frontend:'Исправить страницу клиента',sysadmin:'Настроить резервную копию'})[s.role],description:'+140 CR, −18 фокуса, +15 стресса.'}];}
export function act(s,id){requireStage(s);if(s.actions>=2)throw Error('Лимит: два дополнительных действия в день');const e={rest:[s.inventory.includes('chair')?40:30,-22,0,0,0],learn:[-10,2,-30,20,0],talk:[3,-12,0,0,8],freelance:[-18,15,140,0,0]}[id];if(!e)throw Error('Действие не найдено');if(s.money+e[2]<0)throw Error('Не хватает 30 CR');if(e[0]<0&&s.focus<-e[0])throw Error('Сначала восстанови фокус');s.focus=clamp(s.focus+e[0]);s.stress=clamp(s.stress+e[1]);s.money+=e[2];s.xp+=e[3];s.reputation=clamp(s.reputation+e[4]);if(e[3])s.lastXpDay=s.day;s.actions++;s.log.unshift(`День ${s.day}: ${actions(s).find(a=>a.id===id).name}.`);}
export function task(s){const r=role(s);const index=7+(s.workCount%(r.questions.length-7));return {...r.questions[index],key:`day-${s.day}`,title:rank(s)<2?'Задача специалиста':rank(s)<4?'Ревью и архитектура':'Решение тимлида',reward:160+rank(s)*75+(s.inventory.includes('special')?80:0),xp:75+(s.inventory.includes('monitor')?15:0),context:`${r.company}. ${['Проверь решение перед первой поставкой.','Команда готовит новую версию. Выбери устойчивый подход.','Заказчик ждёт результат. Объясни правильное решение.'][s.workCount%3]}`};}
// Reward and taskDone are updated together, preventing repeated payouts for one task.
export function answerTask(s,index){const q=task(s);if(!Number.isInteger(index)||!q.options[index])throw Error('Выбери ответ');return settleTask(s,index===q.answer,q);}
// The practical UI calls this only after the puzzle reaches its solved state.
export function completePracticalTask(s){const q={...task(s),why:'Практическая работа выполнена. Результат проверен в учебной среде.'};return settleTask(s,true,q);}
function settleTask(s,correct,q){requireStage(s);if(s.taskDone)throw Error('Задача дня уже сдана');if(s.focus<12)throw Error('Нужно 12 фокуса. Сделай перерыв или восстановление.');const prev=rank(s);s.focus=clamp(s.focus-(s.inventory.includes('automation')?10:18));s.stress=clamp(s.stress+MODES[s.mode].stress+(correct?0:8));s.taskAttempt++;s.lastTask={correct,why:q.why,reward:correct?q.reward:0,xp:correct?q.xp:0};if(correct){s.taskDone=true;s.workCount++;s.xp+=q.xp;s.money+=q.reward;s.reputation=clamp(s.reputation+5);s.score+=100;s.lastXpDay=s.day;if(!s.mastered.includes(q.id))s.mastered.push(q.id);}else s.reputation=clamp(s.reputation-3);s.lastTask.promoted=rank(s)>prev?RANKS[rank(s)].name:null;s.log.unshift(`День ${s.day}: ${correct?'задача принята':'ошибка, доступна повторная попытка'}. ${correct?'+'+q.reward+' CR.':''}`);return s.lastTask;}
// Recovery always remains available: resource mistakes must not soft-lock a learning game.
export function recover(s){requireStage(s);s.focus=clamp(s.focus+35);s.stress=clamp(s.stress-20);s.reputation=clamp(s.reputation-2);s.log.unshift('Внеплановая пауза: +35 фокуса, −20 стресса, −2 репутации.');}
export function payroll(s){return s.company?s.company.staff.reduce((n,e)=>n+e.salary,0):0;}
export function companyPrice(){return 3800;}
export function acquire(s,name){requireStage(s);if(s.company)throw Error('Компания уже твоя');if(rank(s)<4)throw Error('Выкуп доступен с ранга Тимлид');if(s.money<companyPrice())throw Error('Нужно 3 800 CR');s.money-=companyPrice();s.company={name:String(name).trim().slice(0,28)||role(s).company,level:1,staff:[],contractDone:false,contracts:0,revenue:0};s.score+=800;s.log.unshift('Ты выкупил компанию. Открыты найм, контракты и расширение.');}
export const CANDIDATES=[{id:'maya',name:'Майя',role:'frontend',salary:50,fee:280},{id:'timur',name:'Тимур',role:'frontend',salary:60,fee:340},{id:'liza',name:'Лиза',role:'frontend',salary:45,fee:250},{id:'mark',name:'Марк',role:'sysadmin',salary:55,fee:300},{id:'nika',name:'Ника',role:'security',salary:65,fee:380},{id:'leo',name:'Лев',role:'frontend',salary:60,fee:340}];
function owner(s){requireStage(s);if(!s.company)throw Error('Сначала выкупи компанию');}
export function hire(s,id){owner(s);const e=CANDIDATES.find(c=>c.id===id);if(!e||s.company.staff.some(c=>c.id===id))throw Error('Кандидат недоступен');if(s.company.staff.length>=s.company.level*2)throw Error('Сначала расширь офис');if(s.money<e.fee)throw Error('Не хватает денег на найм');s.money-=e.fee;s.company.staff.push({...e});s.score+=250;s.log.unshift(`${e.name} в команде. Зарплата ${e.salary} CR/день.`);}
export function expand(s){owner(s);if(s.company.level>=3)throw Error('Офис уже максимального уровня');const cost=s.company.level*1000;if(s.money<cost)throw Error('Не хватает денег на расширение');s.money-=cost;s.company.level++;s.score+=300;s.log.unshift('Офис расширен: '+s.company.level*2+' рабочих мест.');}
export function contract(s,index){owner(s);if(s.company.contractDone)throw Error('Сегодня контракт уже выполнен');if(s.company.staff.length<1)throw Error('Нужен хотя бы один сотрудник');const q=role(s).questions[(s.company.contracts%3)+7];if(!Number.isInteger(index)||!q.options[index])throw Error('Выбери решение');if(index!==q.answer){s.stress=clamp(s.stress+8);return {correct:false,why:q.why};}return settleContract(s,q.why);}
export function completePracticalContract(s){return settleContract(s,'Командный результат проверен и передан заказчику.');}
function settleContract(s,explanation){owner(s);if(s.company.contractDone)throw Error('Сегодня контракт уже выполнен');if(s.company.staff.length<1)throw Error('Нужен хотя бы один сотрудник');const revenue=400+s.company.staff.length*100;s.company.contractDone=true;s.company.contracts++;s.company.revenue+=revenue;s.money+=revenue;s.score+=200;s.log.unshift(`Контракт принят: +${revenue} CR.`);return {correct:true,why:explanation,reward:revenue};}
// Charge costs before advancing the day. A blocked payment must not advance the calendar.
export function endDay(s){requireStage(s);if(!s.taskDone)throw Error('Сначала реши задачу дня');const expenses=MODES[s.mode].cost+payroll(s);if(s.money<expenses)throw Error(`На расходы дня нужно ${expenses} CR. Выполни контракт, возьми фриланс или согласуй аванс.`);s.money-=expenses;s.day++;s.actions=0;s.taskDone=false;s.taskAttempt=0;s.lastTask=null;s.focus=clamp(s.focus+30);s.stress=clamp(s.stress-(s.inventory.includes('plant')?13:10));s.nextEvent=s.worldSeconds+45;if(s.company)s.company.contractDone=false;if((s.day-1)%7===0){s.releaseCount++;s.score+=150;s.money+=200;s.log.unshift('Недельный релиз завершён: +200 CR и +150 очков.');}if(s.nextCrisis){s.pending='promise';s.nextCrisis=false;}if(s.company?.level===3&&s.company.staff.length===6&&s.company.contracts>=3){s.finished=true;}s.log.unshift(`День ${s.day-1} завершён. Расходы ${expenses} CR. Новый день начался.`);}
export function advance(s){owner(s);if(s.money>=MODES[s.mode].cost+payroll(s))throw Error('Средств на день уже достаточно');s.money+=300;s.reputation=clamp(s.reputation-10);s.score=Math.max(0,s.score-100);s.log.unshift('Согласован аванс: +300 CR, −10 репутации, −100 очков.');}
export const EVENTS={burnout:{title:'Слишком много задач',text:'Из-за усталости ты пропустил важную проверку. Команда готова помочь.',options:[{text:'Признать риск и попросить помощь',hint:'−25 стресса, +15 фокуса, +3 репутации',effect:{stress:-25,focus:15,reputation:3}},{text:'Закончить ночью в одиночку',hint:'+12 стресса, −20 фокуса; последствия завтра',effect:{stress:12,focus:-20,nextCrisis:true}}]},budget:{title:'Бюджет на исходе',text:'Небольшой заказ поможет покрыть расходы, но отнимет силы.',options:[{text:'Взять оплачиваемую диагностику',hint:'+180 CR, −10 фокуса, +8 стресса',effect:{money:180,focus:-10,stress:8}},{text:'Попросить команду о поддержке',hint:'+100 CR, −3 репутации',effect:{money:100,reputation:-3}}]},stagnation:{title:'Время развивать навык',text:'Несколько дней без роста. Наставник предлагает учебный разбор.',options:[{text:'Разобрать задачу с наставником',hint:'+25 XP, −10 фокуса',effect:{xp:25,focus:-10}},{text:'Сначала отдохнуть',hint:'+15 фокуса, −10 стресса',effect:{focus:15,stress:-10}}]},scope:{title:'Ещё одна «маленькая» задача',text:'Клиент просит добавить функцию до дедлайна. Как поступишь?',options:[{text:'Оценить объём и согласовать новый срок',hint:'+6 репутации, −5 стресса',effect:{reputation:6,stress:-5}},{text:'Пообещать всё без оценки',hint:'+10 стресса, +80 CR; последствия завтра',effect:{stress:10,money:80,nextCrisis:true}}]},help:{title:'Коллега предлагает ревью',text:'Второй взгляд поможет заметить ошибку раньше релиза.',options:[{text:'Разобрать решение вместе',hint:'+15 фокуса, −10 стресса',effect:{focus:15,stress:-10}},{text:'Обменяться опытом',hint:'+15 XP, +3 репутации',effect:{xp:15,reputation:3}}]},promise:{title:'Вчерашнее обещание',text:'Команда рассчитывала на результат. План нужно скорректировать.',options:[{text:'Объяснить ситуацию и пересогласовать план',hint:'−7 репутации, −10 стресса',effect:{reputation:-7,stress:-10}},{text:'Оплатить помощь',hint:'−100 CR, −15 стресса',effect:{money:-100,stress:-15}}]}};
export function tickWorld(s,dt=1){if(s.stage!=='career'||s.pending)return;s.worldSeconds+=dt;if(s.worldSeconds<s.nextEvent)return;const id=s.stress>80?'burnout':s.money<100?'budget':s.day-s.lastXpDay>3?'stagnation':Math.floor(s.worldSeconds/45)%2?'scope':'help';s.pending=id;s.nextEvent=s.worldSeconds+(s.stress>80?15:60);}
export function chooseEvent(s,index){const e=EVENTS[s.pending]?.options[index];if(!e)throw Error('Выбери вариант');if(e.effect.money<0&&s.money<-e.effect.money)throw Error('Недостаточно денег, выбери другое решение');for(const[k,v]of Object.entries(e.effect)){if(k==='nextCrisis')s.nextCrisis=v;else{s[k]+=v;if(['focus','stress','reputation'].includes(k))s[k]=clamp(s[k]);}}if(e.effect.xp)s.lastXpDay=s.day;s.log.unshift(EVENTS[s.pending].title+': '+e.text);s.pending=null;}
export function leaderboard(s){const own={name:s.name,profession:role(s).name,score:s.score,money:s.money,employees:s.company?.staff.length||0,you:true};const bots=[['Линк','frontend',300,1200,2],['Вега','security',180,850,1],['Пиксель','frontend',100,600,0],['Пинг','sysadmin',240,950,2],['Багхантер','frontend',130,700,1]].map(([name,id,base,money,staff],i)=>({name,profession:ROLES.find(r=>r.id===id).name,score:base+s.day*(55+i*10),money:money+s.day*60,employees:s.day>10?Math.min(6,staff+2):staff,you:false}));return [own,...bots].sort((a,b)=>b.score-a.score);}
export function restore(raw){const s=JSON.parse(raw);if(s&&['backend','qa'].includes(s.role))s.role='frontend';if(s?.company?.staff)for(const person of s.company.staff){if(['backend','qa'].includes(person.role))person.role='frontend';}const fail=()=>{throw Error('Сохранение повреждено или относится к старой версии. Старый прогресс не удалён.');};if(s.version!==2||!ROLES.some(r=>r.id===s.role)||!MODES[s.mode]||!['quiz','bossReady','boss','bossFailed','career'].includes(s.stage)||typeof s.name!=='string')fail();for(const k of['day','xp','money','focus','stress','reputation','score','actions','workCount','quizIndex','bossIndex','bossHp','bossRemaining','worldSeconds','nextEvent','lastXpDay','releaseCount','taskAttempt'])if(!Number.isFinite(s[k])||s[k]<0)fail();if(s.focus>100||s.stress>100||s.reputation>100||s.actions>2||s.quizIndex>4||s.bossIndex>3||s.bossHp>3||s.day<1||!Number.isInteger(s.day))fail();for(const k of ['inventory','log','quizAnswers','bossWrong','mastered'])if(!Array.isArray(s[k]))fail();if(s.inventory.some(id=>!shop(s).some(i=>i.id===id))||new Set(s.inventory).size!==s.inventory.length||s.pending&&!EVENTS[s.pending])fail();if(s.stage==='quiz'&&s.quizIndex>=4||s.stage==='boss'&&(s.bossIndex>=3||s.bossHp===0)||s.stage==='career'&&s.bossIndex!==3)fail();if(s.company){const c=s.company;if(typeof c.name!=='string'||![1,2,3].includes(c.level)||!Array.isArray(c.staff)||c.staff.length>c.level*2||!Number.isInteger(c.contracts)||c.contracts<0||!Number.isFinite(c.revenue)||c.revenue<0)fail();if(c.staff.some(e=>!CANDIDATES.some(x=>x.id===e.id&&x.salary===e.salary))||new Set(c.staff.map(e=>e.id)).size!==c.staff.length)fail();}s.log=s.log.slice(0,100);return s;}
